扫描命中行的代码上下文（±25 行窗口，L<n> 为包内原始行号）：
L1: #!/usr/bin/env node
L2: /*
L3:  * apply.js - install / remove the Capri settings panel into the OpenCode desktop app.
L4:  *
L5:  * This addon shares the append-only main entry out/main/oc-addons.js with the
L6:  * other addons (DeepSeek, Freelancer, Skills). install appends:
L7:  *   + out/main/capri-main.js       (IPC bridge to the Capri app's local API)
L8:  *   + out/renderer/capri-panel.js  (launcher icon + settings panel)
L9:  *   + out/main/oc-addons.js        (shared loader; patched to import capri-main.js)
L10:  *   ~ package.json                 (main -> ./out/main/oc-addons.js)
L11:  *   ~ out/preload/index.js         (expose window.api.capri*)
L12:  *   ~ out/renderer/index.html      (<script src="./capri-panel.js">)
L13:  *
L14:  * Existing data is never moved (only appended). remove neutralizes this addon
L15:  * (its main module becomes an empty stub) and strips its renderer script tag /
L16:  * preload lines, without touching other addons. restore-all copies the shared
L17:  * pristine backup back over app.asar. Run while OpenCode is closed.
L18:  *
L19:  *   node apply.js install|remove|restore-all|status|verify [--app <dir>] [--force]
L20:  */
L21: "use strict";
L22: 
L23: const fs = require("fs");
L24: const path = require("path");
L25: const crypto = require("crypto");
L26: const { execSync } = require("child_process");
L27: 
L28: const SHARED_BACKUP_SUFFIX = ".ocaddons-backup";
L29: const BLOCK_SIZE = 4194304;
L30: const MARKER = "capri-panel.js";
L31: const SCRIPT_TAG = '<script src="./capri-panel.js" defer></script>';
L32: const REMOVED_SENTINEL = "/* oc-addon-removed: capri */";
L33: const CAPRI_IMPORT = "./capri-main.js";
L34: 
L35: const MAIN_PARTS = ["out", "main", "capri-main.js"];
L36: const PANEL_PARTS = ["out", "renderer", "capri-panel.js"];
L37: const PRELOAD_PARTS = ["out", "preload", "index.js"];
L38: const PRELOAD_PARTS_CJS = ["out", "preload", "index.cjs"];
L39: const INDEX_PARTS = ["out", "renderer", "index.html"];
L40: const PKG_PARTS = ["package.json"];
L41: const LOADER_PARTS = ["out", "main", "oc-addons.js"];
L42: const LOADER_MAIN = "./out/main/oc-addons.js";
L43: const BASE_MAIN = "./out/main/index.js";
L44: 
L45: // Shared loader entry. Keep the addon list in sync with the other addons:
L46: // whichever addon installs first creates it, the others reuse or extend it.
L47: const LOADER_SRC =
L48:   "/* oc-addons loader - shared entry for OpenCode desktop addons.\n" +
L49:   " * Loads the base app, then any present addon main module. Addons are\n" +
L50:   " * append-only; a removed addon is neutralized to a no-op stub. */\n" +
L51:   'import "./index.js";\n' +

扫描命中行的代码上下文（±25 行窗口，L<n> 为包内原始行号）：
L5:  * shared entry out/main/oc-addons.js (see apply.js). It proxies a few IPC calls
L6:  * to the Capri app's local HTTP API (127.0.0.1:47823):
L7:  *
L8:  *   capri-state   -> app status + config + plugin + Ollama models
L9:  *   capri-config  -> patch a setting ({ claude, muted, volume, scale, ... })
L10:  *   capri-command -> quick action (teleport, satellite, report, chat, demo, ...)
L11:  *   capri-models  -> Ollama model names
L12:  *   capri-plugin  -> install / remove the OpenCode plugin for Capri
L13:  *
L14:  * The renderer is sandboxed (no http), so the calls live here in main.
L15:  */
L16: import { ipcMain } from "electron";
L17: import http from "node:http";
L18: 
L19: const PORT = Number(process.env.CAPRI_PORT) || 47823;
L20: const OLLAMA = normalizeBase(process.env.OLLAMA_HOST || "http://127.0.0.1:11434");
L21: 
L22: function normalizeBase(value) {
L23:   const text = String(value || "").trim().replace(/\/+$/, "");
L24:   return /^https?:\/\//i.test(text) ? text : "http://" + text;
L25: }
L26: 
L27: function request(url, { method = "GET", body, timeout = 2000 } = {}) {
L28:   return new Promise((resolve, reject) => {
L29:     const payload = body === undefined ? null : Buffer.from(JSON.stringify(body), "utf8");
L30:     const req = http.request(url, {
L31:       method,
L32:       timeout,
L33:       headers: payload
L34:         ? { "content-type": "application/json", "content-length": payload.length }
L35:         : undefined,
L36:     }, (res) => {
L37:       const chunks = [];
L38:       res.on("data", (chunk) => chunks.push(chunk));
L39:       res.on("end", () => {
L40:         const text = Buffer.concat(chunks).toString("utf8");
L41:         let json = {};
L42:         try { json = text ? JSON.parse(text) : {}; } catch (e) { json = { ok: false, error: "invalid JSON" }; }
L43:         resolve(json);
L44:       });
L45:     });
L46:     req.on("timeout", () => { req.destroy(new Error("timeout")); });
L47:     req.on("error", reject);
L48:     if (payload) req.write(payload);
L49:     req.end();
L50:   });
L51: }
L52: 
L53: function capri(path, options) {
L54:   return request(`http://127.0.0.1:${PORT}${path}`, options);
L55: }
